const OC43_GLYPHS=Object.freeze({busy:'M4 7h16v13H4z M9 7V4h6v3 M4 12h16 M10 12v3h4v-3',meeting:'M9 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M4 19v-2a5 5 0 0 1 10 0v2 M16 5a3 3 0 0 1 0 6 M16 13a5 5 0 0 1 4 5v1',break:'M20 15.5A8 8 0 0 1 8.5 4 9 9 0 1 0 20 15.5 M15 3h5l-5 5h5',away:'M10 4H4v16h6 M9 12h11 M16 8l4 4-4 4',dnd:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18 M7 12h10'});
function statusIcon(key){const path=OC43_GLYPHS[key];if(!path)return null;const svg=document.createElementNS('http://www.w3.org/2000/svg','svg'),line=document.createElementNS('http://www.w3.org/2000/svg','path');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');line.setAttribute('d',path);line.setAttribute('fill','none');line.setAttribute('stroke','currentColor');line.setAttribute('stroke-width','2');line.setAttribute('stroke-linecap','round');line.setAttribute('stroke-linejoin','round');svg.append(line);return svg;}
