function changeHistory(from,to){if(!from.length)return;to.push(clone());map=JSON.parse(from.pop());selected=null;studioSelected=null;render();persist();}
function captureOwners(){ownerData=new Map(desks().filter(([,c])=>c.name).map(([,c])=>[c.id,{name:c.name,status:c.status,connection:c.connection,personalStatus:c.personalStatus,statusMessage:c.statusMessage,profileCaption:c.profileCaption,visualOnly:c.visualOnly,visualPose:c.visualPose}]));protectedIds=new Set(ownerData.keys());}
function keepOwners(p){const missing=floor.missingOwned(p,protectedIds);if(missing.length){studioNotify('ไม่สามารถลบโต๊ะที่มีเจ้าของ: '+missing.slice(0,8).join(', '));return false;}for(const c of Object.values(p.cells))if(c.type==='desk'&&ownerData.has(c.id))Object.assign(c,ownerData.get(c.id));p.nextId=Math.max(p.nextId,map.nextId);return true;}
