const edgeStudio=window.OC612_STUDIO;
function edgeDraft(){return edgeStudio.edgeMode(map);}
function paintDraftEdges(key,b){if(!edgeDraft())return;const [x,y]=key.split(',').map(Number);for(const side of ['N','E','S','W']){const k=edgeStudio.edgeForCell(x,y,side),v=map.wallEdges[k],owner=edgeStudio.edgeOwner(map,k);if(!v||owner.key!==key||owner.side!==side)continue;const n=el('span','floor-wall-edge wall-side-'+side+(['door','glass','glassDoubleStart','glassDoubleEnd'].includes(v.type)?' floor-door-edge':'')+(v.type==='glass'?' floor-glass-edge':'')+(v.type==='window'?' floor-window-edge':'')+(edgeStudio.doubleDoor(v)?' floor-double-glass '+(v.type==='glassDoubleStart'?'double-start':'double-end'):''));n.dataset.wallEdge=k;b.append(n);}}
function drawCell(key){const b=document.getElementById('c'+key);if(!b)return;const c=map.cells[key];b.className='cell '+(c?.type||'')+((editing?studioSelected:selected)===key?' selected':'');for(const side of ['N','S','W','E']){const [x,y]=key.split(',').map(Number),boundary=side==='N'?y===0:side==='S'?y===map.rows-1:side==='W'?x===0:x===map.cols-1;if(boundary&&map.edges?.[side+':'+('NS'.includes(side)?x:y)])b.classList.add('edge-'+side);}b.replaceChildren();paintDraftEdges(key,b);delete b.dataset.connection;b.title=c?.type==='desk'?(adminMode?`${c.label} ${c.name}`:`${c.name||'โต๊ะว่าง'}${c.name&&!c.visualOnly?' · '+OC42_STATES[oc42State(c)].label:''}`):(adminMode?c?.type||'Empty':'');b.setAttribute('aria-label',adminMode?`${key}: ${b.title}`:b.title||'พื้นที่ออฟฟิศ');if(!c||c.type==='aisle')return;if(c.type==='stairs'){const h=window.OC671_CORE.hallAt(map,key);if(h){b.classList.add('oc671-stair-part');const [sx,sy]=key.split(',').map(Number);if(sx>h.x){b.classList.add('oc671-flight');b.dataset.stairDirection=sy===h.y?'←':sy===h.y+2?'→':'↓';}b.title='โถงบันไดลง 4 × 3 · ปิดใช้งาน';b.setAttribute('aria-label',key+': '+b.title);if(key===h.anchor)b.append(el('span','oc671-stair-caption','ชานพัก'));return;}}if(shapes.kinds.has(c.type)||c.type==='void'){b.title=shapes.names[c.type];b.setAttribute('aria-label',key+': '+b.title);b.dataset.part=c.part??'';b.dataset.rotation=c.rotation;if(c.type==='roundTable'){b.classList.add('round-table-part','round-part-'+c.part);b.append(el('span','round-table-art'));}if(c.part===0)b.append(el('span','floor-object-label',shapes.names[c.type]));return;}if(c.type==='roundTable'){b.classList.add('round-table-part','round-part-'+c.part);b.title='โต๊ะกลม 2 × 2';b.setAttribute('aria-label',key+': '+b.title);b.append(el('span','round-table-art'));return;}if(['wall','door'].includes(c.type)){const studio=window.OC612_STUDIO,[x,y]=key.split(',').map(Number);if(studio.reserved(map,x,y)){const stair=studio.stairwell(map);b.classList.add('floor-stairs-reserved');b.title='ช่องบันได (ปิดใช้งาน)';b.setAttribute('aria-label',key+': '+b.title);if(x===stair.x+stair.w-1){b.classList.add('floor-stairs-flight');b.append(el('span','floor-stairs-label','↓'));}return;}const shape=studio.wallGeometry(map,x,y);b.classList.add('floor-edge-architecture');for(const r of shape.runs){const n=el('span','floor-wall-edge wall-side-'+r.side+(r.door?' floor-door-edge':'')+(r.glass?' floor-glass-edge':''));b.append(n);}return;}const f=el('div','sprite');let angle=c.rotation;f.style.transform=`rotate(${angle}deg)`;const img=el('img','asset');img.src=`assets/${c.type}.svg`;img.alt='';img.draggable=false;f.append(img);if(c.type==='desk'&&c.name&&c.status==='online'){b.classList.toggle('oc522-sleep',c.personalStatus==='break'||c.visualPose==='sleep');const w=el('img','worker-sprite');w.src='assets/worker.svg';w.alt='';f.append(w);}b.append(f);if(c.type==='desk'){b.dataset.connection=c.connection||'unknown';b.append(el('span','desk-id',adminMode?c.label:(c.visualOnly?'':c.name||'')));if(!c.visualOnly)b.append(statusDot(c));}}
function render(){if(editing)cancelFloorGesture();document.body.classList.toggle('admin-mode',adminMode);document.body.classList.toggle('editor-mode',editing);$('pageLabel').textContent=adminMode?'Management':'Main office';$('adminLink').hidden=adminMode||!window.OC41?.isAdmin();$('backOffice').hidden=!adminMode;$('myDesk').hidden=adminMode;$('chatHub').hidden=adminMode;const g=$('grid');g.className=editing?'editing':'';g.style.gridTemplateColumns=`repeat(${map.cols},var(--cell))`;g.replaceChildren();const frag=document.createDocumentFragment();for(let y=0;y<map.rows;y++)for(let x=0;x<map.cols;x++){const k=`${x},${y}`,b=el('button','cell');b.id='c'+k;b.dataset.key=k;b.type='button';frag.append(b);}g.append(frag);Object.keys(map.cells).forEach(drawCell);if(edgeDraft())for(const k of Object.keys(map.wallEdges)){const o=edgeStudio.edgeOwner(map,k);if(!map.cells[o.key])drawCell(o.key);}for(const key of Object.keys(map.edges||{})){const [side,n]=key.split(':'),i=+n,k=side==='N'?`${i},0`:side==='S'?`${i},${map.rows-1}`:side==='W'?`0,${i}`:`${map.cols-1},${i}`;const b=document.getElementById('c'+k);if(b)b.classList.add('edge-'+side);}if(selected)drawCell(selected);paint672Marks();$('cols').value=map.cols;$('rows').value=map.rows;$('toolbar').hidden=!editing;if(editing&&!window.office3D)$('stage').hidden=false;$('edit').textContent=editing?'Exit editor':'Edit floor plan';$('subtitle').textContent=editing?'Layout Studio · Draft only':'Hover to explore · click a desk to interact';setZoom(zoom);renderPeople();renderDetails();refreshTools();window.office3D?.sync();window.OC50?.refreshUI();}
function setZoom(z){if(window.office3D?.active()){window.office3D.zoomTo(z);return;}zoom=Math.max(.25,Math.min(2.5,z));$('grid').style.setProperty('--cell',`${Math.round(84*zoom)}px`);$('zoomValue').textContent=Math.round(zoom*100)+'%';}
function fit(){if(window.office3D?.active()){window.office3D.fit();return;}setZoom(Math.min(1,($('viewport').clientWidth-50)/(map.cols*84),($('viewport').clientHeight-50)/(map.rows*84)));}
function desks(){return Object.entries(map.cells).filter(([,c])=>c.type==='desk');}
