function select(k){const old=selected;selected=map.cells[k]?.type==='desk'?k:null;chatOpen=false;if(old)drawCell(old);if(selected)drawCell(selected);renderDetails();window.OC64?.deskSelected(selected?map.cells[selected]:null);window.office3D?.highlight(selected);}
function renderDetails(){const d=$('details');d.replaceChildren();const c=map.cells[selected];$('deskPanel').hidden=!c||c.type!=='desk';if(!c||c.type!=='desk')return;const card=el('div','detail-card');const pill=el('span','desk-pill');pill.append(statusDot(c),document.createTextNode(OC42_STATES[oc42State(c)].label));const art=!editing&&c.name&&!c.visualOnly?window.OC50?.portrait?.(c.id):null;const identity=art?el('div','oc614-profile-identity'):card;const copy=art?el('div','oc614-profile-copy'):card;if(art){const frame=el('div','oc614-profile-portrait');frame.append(art);identity.append(frame,copy);card.append(identity);}else card.append(el('div','avatar',c.name?c.name.slice(0,2).toUpperCase():'D'));copy.append(el('h3','',c.name||(adminMode?'Available desk':'โต๊ะว่าง')));if(adminMode)copy.append(el('p','muted',c.label));if(!c.visualOnly)copy.append(pill);if(!editing&&!c.visualOnly&&c.profileCaption)copy.append(el('p','oc633-character-caption',c.profileCaption));if(!editing&&c.connection==='online'&&c.statusMessage)copy.append(el('p','desk-status-note',c.statusMessage));if(adminMode&&editing){const edit=el('button','primary','Edit desk label');edit.onclick=()=>{$('deskLabel').value=c.label;$('dialog').showModal();};card.append(edit);}else if(window.OC41)window.OC41.renderDesk(c,card);else card.append(el('p','muted','กำลังเชื่อมต่อออฟฟิศ…'));d.append(card);}
function preview(kind,c){const title=$('previewTitle'),text=$('previewText'),body=$('previewBody');body.replaceChildren();const field=(a,b)=>{const row=el('div','preview-field');row.append(el('span','',a),el('strong','',b));body.append(row);};const feature=(a,b)=>{const row=el('div','preview-feature');row.append(el('span','',a),el('div','',b));body.append(row);};if(kind==='sit'){title.textContent='Make this desk yours';text.textContent='Choose a vacant desk and register with your employee number. You will keep this seat until you move.';field('Selected desk',c.label);field('Employee ID','Your employee number');field('Nickname','Display name');field('Password','Set during registration');}else if(kind==='my'){title.textContent='Your desk, your space';text.textContent='In V4.1, log in with your employee ID and password to return to your own desk.';feature('01','Choose a vacant desk');feature('02','Set your nickname and personal status');feature('03','Return to your desk from any device');}else if(kind==='message'){title.textContent='Message '+(c?.name||'');text.textContent='Private messages will be delivered to this employee after accounts and the shared database are connected.';field('Recipient',c?.name||'Employee');field('Desk',c?.label||'—');}else if(kind==='group'){title.textContent='Private group chat';text.textContent='Create a private conversation and invite colleagues. Invitations and access will be enforced by the database.';field('Invitee',c?.name||'Select colleagues');}else{title.textContent='Messages';text.textContent='Your conversations will appear here once the shared office and chat modules are connected.';feature('DM','Private messages between employees');feature('GR','Private groups and invitations');feature('•','Unread messages and notifications');}$('previewDialog').showModal();}
function hoverDesk(k,clientX,clientY){const tip=$('deskHover'),c=map.cells[k];if(editing||!c||c.type!=='desk'){tip.hidden=true;return;}$('hoverTitle').textContent=c.name||(adminMode?'Available desk':'โต๊ะว่าง');const st=OC42_STATES[oc42State(c)];$('hoverMeta').textContent=c.visualOnly?'':(adminMode?c.label+' · ':'')+st.label+(c.connection==='online'&&c.statusMessage?' · '+c.statusMessage:'');$('hoverMeta').hidden=!!c.visualOnly;$('hoverTitle').style.setProperty('--presence-color',st.color);tip.dataset.presence=oc42State(c);tip.hidden=false;const r=$('viewport').getBoundingClientRect();const x=clientX-r.left+$('viewport').scrollLeft,y=clientY-r.top+$('viewport').scrollTop;tip.style.left=Math.max(6,Math.min(x+16,r.width+$('viewport').scrollLeft-tip.offsetWidth-8))+'px';tip.style.top=Math.max(6,Math.min(y+16,r.height+$('viewport').scrollTop-tip.offsetHeight-8))+'px';}
function hideHover(){$('deskHover').hidden=true;}
function refreshTools(){const studio=window.OC612_STUDIO, c=map.cells[studioSelected];$('studioSelection').textContent=studioSelected?(c?`${studioSelected} · ${c.label||c.type} · ${c.rotation}°`:`${studioSelected} · พื้นว่าง`):'ยังไม่ได้เลือกวัตถุ';$('studioRotate').disabled=!!(c?.type==='stairs'&&studioSelected&&window.OC671_CORE.hallAt(map,studioSelected))||!c||c.type==='roundTable'||c.type==='void'||c.type==='door'||(studioSelected&&!shapes.kinds.has(c.type)&&studio.reserved(map,...studioSelected.split(',').map(Number)));$('studioRotate').title=c?.type==='wall'?'หมุนแนวผนัง: ขอบบน / ขอบขวา / ขอบซ้าย':'หมุนวัตถุที่เลือก';$('studioFlush').disabled=!studio.canAlign(c)||!window.OC41?.studioReady();$('studioCenter').disabled=!studio.canAlign(c)||!window.OC41?.studioReady();$('studioDelete').disabled=!c||floor.owned(c,protectedIds);$('studioView').textContent=studioMode==='3d'?'มุมบน 2D':'มุม 3D';$('studioView').disabled=!window.office3D;for(const id of ['studioCamLeft','studioCamRight','studioCamTop'])$(id).disabled=!window.office3D||studioMode!=='3d';for(const b of $('studioEdgeButtons').querySelectorAll('button')){const side=b.dataset.side;const [x,y]=(studioSelected||'-1,-1').split(',').map(Number);b.disabled=!window.OC41?.studioReady()||!(side==='N'?y===0:side==='S'?y===map.rows-1:side==='W'?x===0:x===map.cols-1);} $('studioEdgeButtons').hidden=!(tool==='window'||tool==='edgeErase');for(const b of $('tools').children){b.classList.toggle('active',b.dataset.tool===tool);b.disabled=((shapes.kinds.has(b.dataset.tool)||['cutFloor','restoreFloor'].includes(b.dataset.tool))&&!window.OC41?.floorReady())||(propTypes.includes(b.dataset.tool)&&!window.OC50?.movementReady())||(['window','edgeErase'].includes(b.dataset.tool)&&!window.OC41?.studioReady());}$('rotate').textContent=`หมุน R (${rotation}°)`;$('undo').disabled=!undo.length;$('redo').disabled=!redo.length;refreshFloorTools();}
for(let i=0;i<types.length;i++){const b=el('button','',labels[i]);b.dataset.tool=types[i];b.onclick=()=>chooseFloorTool(types[i]);$('tools').append(b);}
