function studioSelect(k){k=(map.cells[k]?.type==='stairs'?window.OC671_CORE.hallAt(map,k)?.anchor:null)||shapes.block(map,k)?.anchor||k;const old=studioSelected;studioSelected=k;select(k);if(old)drawCell(old);if(k)drawCell(k);paint672Marks();refreshTools();window.office3D?.highlight(k);}
function studioCommit(message){const C=window.OC671_CORE;if(map.roomTargets){map.roomTargets=C.cleanMarks(map);if(!Object.keys(map.roomTargets).length)delete map.roomTargets;}if(map.personalityBoard&&!C.boardFromMark(map,map.personalityBoard))delete map.personalityBoard;render();persist(message);}
function markDestination(){if(!canEditFloor()||!window.OC41?.marksReady?.()){studioNotify('ติดตั้ง SQL 36 ก่อนกำหนดจุดร่วมกัน');return;}const k=studioSelected,kind=$('oc672MarkKind').value,C=window.OC671_CORE;if(!C.validMark(map,k)){studioNotify('เลือกช่องพื้นว่างที่ต้องการให้ตัวละครเดินไปยืน');return;}const field=window.OC54_MOTION.clearance(map,window.OC612_STUDIO.offset,()=>[0,0]);if(!field.free(...k.split(',').map(Number))){studioNotify('จุดนี้มี Object ขวาง เลือกช่องอื่น');return;}if(kind==='poster'){const side=$('oc672MarkSide').value,edge=window.OC612_STUDIO.edgeForCell(...k.split(',').map(Number),side);const b={edge,cell:k};if(!C.boardFromMark(map,b)){studioNotify('เลือกด้านที่มีผนังทึบติดช่องพื้น');return;}checkpoint();map.personalityBoard=b;}else{checkpoint();map.roomTargets={...C.cleanMarks(map),[kind]:k};}studioCommit('กำหนดจุด '+$('oc672MarkKind').selectedOptions[0].textContent+' ที่ '+k);}
function clearDestination(){if(!canEditFloor()||!window.OC41?.marksReady?.())return;const kind=$('oc672MarkKind').value;checkpoint();if(kind==='poster')delete map.personalityBoard;else if(map.roomTargets){delete map.roomTargets[kind];if(!Object.keys(map.roomTargets).length)delete map.roomTargets;}studioCommit('กลับไปใช้ตำแหน่งอัตโนมัติ');}
$('oc672MarkSave').onclick=markDestination;$('oc672MarkClear').onclick=clearDestination;
function paint672Marks(){if(!editing)return;document.querySelectorAll('#grid .oc672-mark').forEach(n=>n.remove());const C=window.OC671_CORE;for(const [kind,k] of Object.entries(C.cleanMarks(map))){const cell=$('c'+k);if(cell)cell.append(el('span','oc672-mark',({executive:'EX',large:'L',small:'S',kitchen:'K'})[kind]));}const b=C.boardFromMark(map,map.personalityBoard);if(b)$('c'+b.cell)?.append(el('span','oc672-mark oc672-poster-mark','P'));const box=$('oc672MarksInfo');if(box)box.textContent='จุดห้อง '+Object.keys(C.cleanMarks(map)).length+'/4 · โปสเตอร์ '+(b?'กำหนดเอง':'อัตโนมัติ')+' · โถงบันได '+C.halls(map).filter(b=>b.switchback).length+' ชุด (Draft)';}

function placeStairHall(marked=true){if(!canEditFloor()||!window.OC41?.floorReady()||!window.OC41?.edgeReady()){studioNotify('เปิด Edit Floor Plan และแปลงผนังเป็นเส้น Grid ก่อน');return;}try{if(!marked&&!studioSelected){studioNotify('เลือกช่องพื้นด้านซ้ายบนของโถงก่อน');return;}const n=marked?window.OC671_CORE.markedHall(map):window.OC671_CORE.placeHall(map,...studioSelected.split(',').map(Number));if(n===map){studioNotify('มีโถงบันไดนี้อยู่แล้ว');return;}const h=window.OC671_CORE.halls(n).find(b=>b.switchback&&!window.OC671_CORE.hallAt(map,b.anchor));checkpoint();map=n;studioSelected=h?.anchor||studioSelected;selected=null;studioCommit('เพิ่มโถงบันได 4 × 3 · ตรวจภาพก่อนบันทึก');if(studioMode==='2d')document.getElementById('c'+studioSelected)?.scrollIntoView({block:'center',inline:'nearest'});}catch(e){studioNotify(e.message);}}
$('oc671StairPreset').onclick=()=>placeStairHall(true);$('oc671StairManual').onclick=()=>placeStairHall(false);

function studioEdge(k){if(!editing||!window.OC41?.isAdmin()||!window.OC41?.studioReady()||!window.OC612_STUDIO.edgeValid(map,k))return false;if(tool==='edgeErase'){if(!map.edges[k])return false;checkpoint();delete map.edges[k];}else if(tool==='window'){if(map.edges[k])return false;checkpoint();map.edges[k]={type:'window'};}else return false;studioCommit('Window '+k);return true;}
function studioClick(k,hit=null,edge=null){if(!canEditFloor())return false;
 if(!edgeDraft()&&(tool==='window'||tool==='edgeErase')){if(edge)return studioEdge(edge);if(k){studioSelect(k);studioNotify('เลือกด้านขอบ N / E / S / W หรือคลิกแถบขอบในฉาก 3D');}return false;}
 if(edgeDraft()&&edgeTool(tool)){studioNotify('เลือกเส้น Grid ในมุม 2D เพื่อวางหรือแก้ผนัง');return false;}
 if(tool==='select'){studioSelect(hit||k);return true;}
 if(tool==='move'){if(studioSelected&&shapes.kinds.has(map.cells[studioSelected]?.type)){if(!k||k===studioSelected)return false;const q=floor.moveBlock(map,studioSelected,k);if(!q){studioNotify('พื้นที่ใหม่ต้องว่างและรองรับขนาดวัตถุทั้งชุด');return false;}checkpoint();map=q;studioSelected=k;selected=null;studioCommit('ย้ายวัตถุทั้งชุด');return true;}if(studioSelected&&window.OC612_STUDIO.reserved(map,...studioSelected.split(',').map(Number))){studioNotify('ช่องบันไดเป็นชุดเดียว · ใช้เครื่องมือลบหากต้องการนำออก');return false;}if(!studioSelected||!map.cells[studioSelected]){if(hit||map.cells[k])studioSelect(hit||k);else studioNotify('เลือกวัตถุที่จะย้ายก่อน');return false;}if(hit&&hit!==studioSelected&&map.cells[hit]?.type!=='aisle'){studioSelect(hit);return false;}if(!k||k===studioSelected)return false;if(map.cells[k]&&map.cells[k].type!=='aisle'){studioNotify('ช่องนี้มีวัตถุอยู่แล้ว');return false;}checkpoint();map.cells[k]=map.cells[studioSelected];delete map.cells[studioSelected];studioSelected=k;selected=map.cells[k].type==='desk'?k:null;studioCommit('Moved existing object · ID preserved');return true;}
 if(hit)k=hit;if(!k||!floor.isBatch(tool))return false;return applyFloor(k,k,'single');
}
for(const [kind,label] of [['move','Move object'],['edgeErase','Remove edge window']]){const b=el('button','',label);b.dataset.tool=kind;b.onclick=()=>chooseFloorTool(kind);$('tools').append(b);}
$('studioView').onclick=()=>{if(!canEditFloor())return;cancelFloorGesture();if(studioMode==='2d'&&(['room','pan'].includes(tool)||(edgeDraft()&&edgeTool(tool))))tool='select';studioMode=studioMode==='3d'?'2d':'3d';refreshTools();window.office3D?.sync();fit();};
$('studioCamLeft').onclick=()=>$('turnLeft').click();$('studioCamRight').onclick=()=>$('turnRight').click();$('studioCamTop').onclick=()=>$('topView').click();
$('studioRotate').onclick=()=>{const c=map.cells[studioSelected];if(canEditFloor()&&shapes.kinds.has(c?.type)&&c.type!=='roundTable'){const q=floor.rotateBlock(map,studioSelected);if(!q){studioNotify('หมุนไม่ได้ · พื้นที่ไม่พอหรือมีวัตถุขวาง');return;}const anchor=shapes.block(map,studioSelected).anchor;checkpoint();map=q;studioSelected=anchor;studioCommit('หมุนวัตถุทั้งชุด');return;}if(!canEditFloor()||!c||c.type==='roundTable'||c.type==='door'||window.OC612_STUDIO.reserved(map,...studioSelected.split(',').map(Number)))return;checkpoint();c.rotation=c.type==='wall'?({0:90,90:270,180:90,270:0}[c.rotation]??0):(c.rotation+90)%360;studioCommit('Rotated selected object');};
$('studioFlush').onclick=()=>{const c=map.cells[studioSelected];if(!canEditFloor()||!window.OC41?.studioReady()||!window.OC612_STUDIO.canAlign(c))return;const [x,y]=studioSelected.split(',').map(Number),r=window.OC612_STUDIO.wallRotation(map,x,y,c);if(window.OC612_STUDIO.legacyDesk(map,x,y,c)){studioNotify('โต๊ะนี้จัดชิดผนังตามผังเดิมอยู่แล้ว');return;}if(r===null){studioNotify('ต้องมีผนังอยู่ติดกับช่องของวัตถุ');return;}checkpoint();c.rotation=r;c.align='wall';studioCommit('Aligned with wall');};
$('studioCenter').onclick=()=>{const c=map.cells[studioSelected];if(!canEditFloor()||!window.OC41?.studioReady()||!window.OC612_STUDIO.canAlign(c))return;const [x,y]=studioSelected.split(',').map(Number);if(window.OC612_STUDIO.legacyDesk(map,x,y,c)){studioNotify('โต๊ะเดิมมีตำแหน่งชิดผนังเฉพาะ ย้ายช่องได้ด้วย Move');return;}checkpoint();c.align='center';studioCommit('Centered object');};
$('studioDelete').onclick=()=>{if(!editing||!map.cells[studioSelected])return;const previous=tool;tool='erase';studioClick(studioSelected,studioSelected);tool=previous;refreshTools();window.office3D?.sync();};
for(const b of $('studioEdgeButtons').querySelectorAll('button'))b.onclick=()=>{if(!studioSelected)return;const [x,y]=studioSelected.split(',').map(Number),side=b.dataset.side;if(edgeDraft()&&edgeTool(tool)){const key=edgeStudio.edgeForCell(x,y,side);applyEdgeItems(tool==='doubleGlassDoor'?floor.doubleDoorItems(map,key):[{key,type:tool==='glassDoor'?'glass':['wallEdgeErase','edgeErase'].includes(tool)?'erase':tool}]);}else studioEdge(side+':'+('NS'.includes(side)?x:y));};
const grid=$('grid');
function canEditFloor(){return editing&&adminMode&&window.OC41?.isAdmin()&&!$('save').disabled;}
function floorCategory(t){return ['wall','door','glassDoor','doubleGlassDoor','stairs','wallEdgeErase','aisle','room','window','edgeErase','doubleDoor','cutFloor','restoreFloor'].includes(t)?'build':['select','move','erase','pan'].includes(t)?'common':'furniture';}
function chooseFloorTool(t){if(!canEditFloor())return;cancelFloorGesture();tool=t;if(edgeDraft()&&t==='doubleDoor')t=tool='doubleGlassDoor';if(floorCategory(t)!=='common')floorGroup=floorCategory(t);if((['room','pan'].includes(t)||(edgeDraft()&&edgeTool(t)))&&studioMode!=='2d'){studioMode='2d';window.office3D?.sync();fit();}refreshTools();window.office3D?.sync();}
const roomBtn=el('button','','สร้างห้อง');roomBtn.dataset.tool='room';roomBtn.type='button';roomBtn.onclick=()=>chooseFloorTool('room');$('tools').append(roomBtn);const panBtn=el('button','','เลื่อนแปลน');panBtn.dataset.tool='pan';panBtn.type='button';panBtn.onclick=()=>chooseFloorTool('pan');$('tools').append(panBtn);
const toolNames={select:'เลือก',pan:'เลื่อนแปลน',move:'ย้าย',erase:'ลบ',room:'สร้างห้อง',wall:'ผนัง',door:'ประตู',aisle:'พื้นทางเดิน',desk:'โต๊ะ',plant:'ต้นไม้',meeting:'โต๊ะประชุม',coffee:'เครื่องชงกาแฟ',water:'ตู้น้ำ',printer:'เครื่องพิมพ์',fridge:'ตู้เย็น',cabinet:'ตู้เอกสาร',sofa:'โซฟา',plants:'มุมต้นไม้',books:'ชั้นหนังสือ',window:'หน้าต่าง',edgeErase:'ลบหน้าต่าง'};
for(const b of $('tools').children){b.type='button';b.textContent=toolNames[b.dataset.tool]||b.textContent;b.title=b.textContent;}
for(const t of ['select','pan','move','erase','room','wall','door','aisle','window','edgeErase','desk','meeting','plant','coffee','water','printer','fridge','cabinet','sofa','plants','books']){const b=$('tools').querySelector(`[data-tool="${t}"]`);if(b)$('tools').append(b);}
function edgeTool(t){return ['wall','door','glassDoor','doubleGlassDoor','wallEdgeErase','room','window','edgeErase'].includes(t);}
for(const [t,label] of [['glassDoor','ประตูกระจก'],['doubleGlassDoor','ประตูกระจกคู่'],['wallEdgeErase','ลบเส้นผนัง'],['stairs','โถงบันไดลง 3 × 2'],['roundTable','โต๊ะกลม 2 × 2'],['longTable','โต๊ะยาว 2 × 1'],['doubleDoor','ประตูกระจกบานคู่ 2 × 1'],['cutFloor','ตัดพื้นที่พื้น'],['restoreFloor','คืนพื้นที่พื้น']]){const b=el('button','',label);b.type='button';b.dataset.tool=t;b.onclick=()=>chooseFloorTool(t);$('tools').append(b);}
// Experimental edge-wall controls are optional on the production page.
const edgeDraftConvert=$('edgeDraftConvert'),edgeDraftNotice=$('edgeDraftNotice');
if(edgeDraftConvert)edgeDraftConvert.onclick=()=>{if(!canEditFloor()||edgeDraft()||!window.OC41?.edgeReady?.())return;if(!confirm('แปลงผนัง ประตู และหน้าต่างทั้งหมดเป็นเส้น Grid ใน Draft? Desk ID และตำแหน่งช่องเดิมคงเดิม ตรวจผัง 3D และทางเดินก่อนบันทึกออนไลน์'))return;let next;try{next=edgeStudio.convertWalls(map);}catch(e){studioNotify(e.message);return;}checkpoint();map=next;tool='wall';floorGroup='build';studioMode='2d';selected=studioSelected=null;studioCommit('แปลงเป็นผนังบนเส้นแล้ว · ยังไม่ได้บันทึกออนไลน์');};
function edgeFromPointer(e,k,axis=null){const b=document.getElementById('c'+k),r=b?.getBoundingClientRect();if(!r||!r.width||!r.height)return null;const [x,y]=k.split(',').map(Number),u=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),v=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height)),choices=[['N',v],['S',1-v],['W',u],['E',1-u]].filter(([s])=>!axis||(axis==='H'?'NS':'WE').includes(s)).sort((a,b)=>a[1]-b[1]);if(!axis&&choices[0][1]>.35)return null;return edgeStudio.edgeForCell(x,y,choices[0][0]);}
function edgeItems(g){if(tool==='doubleGlassDoor')return floor.doubleDoorItems(map,g.edgeStart);if(tool==='room')return floor.roomEdges(map,g.start,g.end,$('floorRoomDoor').checked);const type=tool==='glassDoor'?'glass':['wallEdgeErase','edgeErase'].includes(tool)?'erase':tool;const keys=['door','glassDoor','window'].includes(tool)||$('floorStroke').value==='single'?[g.edgeStart]:floor.edgeLine(map,g.edgeStart,g.edgeEnd);return keys.filter(Boolean).map(key=>({key,type}));}
function edgePreview(g){grid.querySelectorAll('.edge-draft-preview').forEach(n=>n.remove());const items=edgeItems(g);for(const {key,type} of items){const o=edgeStudio.edgeOwner(map,key),b=document.getElementById('c'+o.key);const n=el('span','floor-wall-edge edge-draft-preview wall-side-'+o.side+(type==='erase'?' edge-draft-remove':''));b?.append(n);}$('floorPreviewCount').textContent=`${items.length} เส้น · ไม่กินพื้นที่ช่อง`;}
function applyEdgeItems(items){if(!canEditFloor()||!edgeDraft())return false;let q;try{q=floor.applyEdges(map,items);}catch(e){studioNotify(e.message);return false;}if(!items.length&&tool==='doubleGlassDoor'){studioNotify('ต้องมีเส้น Grid ต่อกัน 2 ช่วง');return false;}if(!q.changed)return false;checkpoint();map=q.plan;studioCommit('แก้ไข '+q.changed+' เส้น');return true;}
function floorOpts(mode){return {mode:mode||$('floorStroke').value,rotation,spacing:Number($('floorSpacing').value),roomDoor:$('floorRoomDoor').checked,protectedIds};}
function refreshFloorTools(){if(!editing)return;if(!edgeDraft()&&['glassDoor','doubleGlassDoor','wallEdgeErase'].includes(tool))tool='select';let mode=studioMode==='2d';document.body.classList.toggle('floor-plan-2d',mode);document.body.classList.toggle('floor-show-details',tool==='select');for(const id of ['floorZoomIn','floorZoomOut','floorFit'])$(id).hidden=!mode;grid.classList.toggle('floor-pan',mode&&tool==='pan');for(const b of $('floorGroups').querySelectorAll('button'))b.setAttribute('aria-pressed',String(b.dataset.floorGroup===floorGroup));for(const b of $('tools').children){let cat=floorCategory(b.dataset.tool);b.hidden=cat!=='common'&&cat!==floorGroup;b.setAttribute('aria-pressed',String(b.dataset.tool===tool));}const isEdge=edgeDraft();const edgeReady=window.OC41?.edgeReady?.()===true;if(edgeDraftConvert){edgeDraftConvert.hidden=isEdge;edgeDraftConvert.disabled=!edgeReady;edgeDraftConvert.title=edgeReady?'แปลงใน Draft ก่อนบันทึก':'ติดตั้ง SQL 34 ก่อน';}if(edgeDraftNotice){edgeDraftNotice.hidden=!isEdge;edgeDraftNotice.textContent=edgeReady?'ผนังอยู่บนเส้น Grid · พื้นสองด้านวางของได้':'ยังบันทึกไม่ได้ · ต้องติดตั้ง SQL 34';}$('save').textContent=isEdge&&!edgeReady?'บันทึกออนไลน์ (รอ SQL)':'บันทึกออนไลน์';$('save').setAttribute('aria-disabled',String(isEdge&&!edgeReady));if(isEdge&&tool==='doubleDoor')tool='doubleGlassDoor';const legacyDouble=$('tools').querySelector('[data-tool=doubleDoor]');if(legacyDouble&&isEdge)legacyDouble.hidden=true;for(const b of $('tools').querySelectorAll('[data-tool=glassDoor],[data-tool=doubleGlassDoor],[data-tool=wallEdgeErase]'))b.hidden=!isEdge||floorGroup!==floorCategory(b.dataset.tool);const batch=mode&&(floor.isBatch(tool)||(isEdge&&edgeTool(tool)));$('floorStroke').disabled=!batch||['room','doubleGlassDoor','stairs','roundTable','longTable','doubleDoor'].includes(tool);$('floorSpacingWrap').hidden=tool!=='desk'||!mode;$('floorRoomDoorWrap').hidden=tool!=='room';$('floorSummary').textContent=`${map.cols} × ${map.rows} ช่อง · ${desks().length} โต๊ะ · ${desks().filter(([,c])=>floor.owned(c,protectedIds)).length} มีเจ้าของ`;$('floorToolHint').textContent=tool==='pan'?'ลากเพื่อเลื่อนแปลน · ไม่เปลี่ยนข้อมูล':tool==='room'?'ลากกรอบอย่างน้อย 3 × 3 ช่อง เพื่อสร้างผนังรอบห้อง':tool==='move'?'เลือกวัตถุ แล้วคลิกช่องว่างเพื่อย้าย · ID โต๊ะคงเดิม':tool==='door'?'คลิกผนังเพื่อเปลี่ยนเป็นประตู · ประตูติดกันเป็นกระจก':tool==='wall'?'ลากตามแนว Grid · แนวตั้งชิดซ้าย (R=90° ชิดขวา)':!mode?'มุม 3D: คลิกวางทีละชิ้น · กลับ 2D เพื่อใช้เครื่องมือลาก':batch?'ลากเพื่อสร้างหลายช่อง · สีเขียว = ทำได้ · สีแดง = ติดวัตถุเดิม':'คลิกเลือกวัตถุหรือขอบพื้น';if(shapes.kinds.has(tool))$('floorToolHint').textContent=(shapes.names[tool]||tool)+' · คลิกมุมซ้ายบน · R หมุนก่อนวาง · ลบ/ย้ายทั้งชุด';if(tool==='cutFloor')$('floorToolHint').textContent='ลากตัดพื้นที่พื้นว่าง · ลบวัตถุออกก่อน · ไม่ตัดโต๊ะที่มีเจ้าของ';if(tool==='restoreFloor')$('floorToolHint').textContent='ลากคืนพื้นในช่องที่เคยตัดออก';if(isEdge&&edgeTool(tool))$('floorToolHint').textContent=tool==='doubleGlassDoor'?'คลิกเส้นแรกของประตู · ใช้ 2 ช่วงต่อกันทางขวาหรือล่าง':tool==='room'?'ลากกรอบห้อง · สร้างผนังตามขอบโดยไม่กินช่องพื้น':tool==='wall'?'เริ่มลากบนเส้นขอบ Grid เพื่อสร้างผนัง':tool==='wallEdgeErase'?'คลิกหรือลากตามเส้นเพื่อลบเฉพาะผนัง':'คลิกเส้น Grid เพื่อวางประตู · ไม่ลบเฟอร์นิเจอร์';}
function clearFloorPreview(){grid.querySelectorAll('.edge-draft-preview').forEach(n=>n.remove());if(!floorGesture)return;for(const k of floorGesture.preview||[]){const b=document.getElementById('c'+k);b?.classList.remove('floor-preview','floor-blocked','floor-same','floor-door-preview');}floorGesture.preview=[];}
function cancelFloorGesture(){if(!floorGesture)return;const id=floorGesture.id;clearFloorPreview();floorGesture=null;const g=$('grid');g.classList.remove('floor-dragging');try{if(g.hasPointerCapture(id))g.releasePointerCapture(id);}catch{}if($('floorPreviewCount'))$('floorPreviewCount').textContent='';}
function drawFloorPreview(){if(!floorGesture)return;clearFloorPreview();const q=floor.inspect(map,tool,floorGesture.start,floorGesture.end,floorOpts());floorGesture.preview=q.cells.map(o=>o.key);for(const o of q.cells){const b=document.getElementById('c'+o.key);b?.classList.add('floor-preview');if(q.atomicBlocked||o.verdict==='blocked')b?.classList.add('floor-blocked');else if(o.verdict==='same')b?.classList.add('floor-same');else if(o.type==='door')b?.classList.add('floor-door-preview');}$('floorPreviewCount').textContent=q.invalid?'พื้นที่ไม่พอ':q.atomicBlocked?(q.internal?'วางไม่ได้ · มีเส้นผนังพาดผ่านพื้นที่':('วางไม่ได้ · ช่อง '+q.cells.filter(c=>c.verdict==='blocked').map(c=>c.key+' ('+(map.cells[c.key]?.type||'reserved')+')').join(', '))):`${q.changed} ช่องที่จะเปลี่ยน${q.blocked?' · ข้าม '+q.blocked+' ช่อง':''}`;}
function applyFloor(a,b,mode){if((shapes.kinds.has(tool)||['cutFloor','restoreFloor'].includes(tool))&&!window.OC41?.floorReady()){studioNotify('ฐานข้อมูลยังไม่รองรับเครื่องมือผังรุ่นใหม่');return false;}if(!canEditFloor()||!floor.isBatch(tool))return false;if(propTypes.includes(tool)&&!window.OC50?.movementReady())return false;let q;try{q=floor.apply(map,tool,a,b,floorOpts(mode));}catch(e){studioNotify(e.message);return false;}if(q.invalid){studioNotify('พื้นที่ไม่พอสำหรับเครื่องมือนี้');return false;}if(q.atomicBlocked){studioNotify('มีวัตถุ ผนัง หรือบันไดเดิมขวาง · วางไม่ได้');return false;}if(!q.applied){if(q.blocked)studioNotify('ข้ามช่องที่มีวัตถุหรือโต๊ะที่มีเจ้าของ');else if(map.cells[a])studioSelect(a);return false;}checkpoint();map=q.plan;studioSelected=map.cells[q.last]?(shapes.block(map,q.last)?.anchor||q.last):null;selected=map.cells[studioSelected]?.type==='desk'?studioSelected:null;studioCommit(`${toolNames[tool]||({stairs:'บันได',roundTable:'โต๊ะกลม'}[tool])||tool} ${q.applied} ช่อง${q.blocked?' · ข้าม '+q.blocked+' ช่อง':''}`);return true;}
function keyAt(e){const cell=document.elementFromPoint(e.clientX,e.clientY)?.closest('.cell');return cell&&grid.contains(cell)?cell.dataset.key:null;}
grid.addEventListener('pointerdown',e=>{const k=e.target.closest('.cell')?.dataset.key;if(!k||e.button!==0)return;if(editing){e.preventDefault();if(!canEditFloor())return;if(floorGesture)return;if(studioMode==='2d'&&tool==='pan'){const v=$('viewport');floorGesture={id:e.pointerId,pan:true,x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop,preview:[]};grid.classList.add('floor-dragging');try{grid.setPointerCapture(e.pointerId);}catch{}return;}if(studioMode==='2d'&&edgeDraft()&&edgeTool(tool)){const ek=tool==='room'?null:edgeFromPointer(e,k);if(tool!=='room'&&!ek){studioNotify('คลิกใกล้เส้นขอบ Grid');return;}floorGesture={id:e.pointerId,start:k,end:k,edgeDraft:true,edgeStart:ek,edgeEnd:ek,preview:[]};try{grid.setPointerCapture(e.pointerId);}catch{}edgePreview(floorGesture);return;}if(studioMode==='2d'&&floor.isBatch(tool)){floorGesture={id:e.pointerId,start:k,end:k,preview:[]};try{grid.setPointerCapture(e.pointerId);}catch{}drawFloorPreview();return;}studioClick(k,map.cells[k]?k:null);return;}if(!adminMode&&window.OC50?.walkMode()){const r=e.target.closest('.cell').getBoundingClientRect(),sx=Math.max(-1,Math.min(1,Math.floor((e.clientX-r.left)/r.width*3)-1)),sy=Math.max(-1,Math.min(1,Math.floor((e.clientY-r.top)/r.height*3)-1));window.OC50.choose({key:k,subX:sx,subY:sy});return;}select(e.target.closest('.oc50-floor-avatar')?.dataset.deskKey||k);});
grid.addEventListener('pointermove',e=>{if(!floorGesture||floorGesture.id!==e.pointerId)return;if(floorGesture.pan){const v=$('viewport');v.scrollLeft=floorGesture.left+floorGesture.x-e.clientX;v.scrollTop=floorGesture.top+floorGesture.y-e.clientY;return;}const k=keyAt(e);if(floorGesture.edgeDraft){if(k){floorGesture.end=k;if(floorGesture.edgeStart)floorGesture.edgeEnd=edgeFromPointer(e,k,floorGesture.edgeStart[0]);edgePreview(floorGesture);}return;}if(k&&k!==floorGesture.end){floorGesture.end=k;drawFloorPreview();}});
grid.addEventListener('pointerup',e=>{if(!floorGesture||floorGesture.id!==e.pointerId)return;const {start,pan}=floorGesture,k=keyAt(e);if(floorGesture.edgeDraft){let items=[];if(k){floorGesture.end=k;if(floorGesture.edgeStart)floorGesture.edgeEnd=edgeFromPointer(e,k,floorGesture.edgeStart[0]);items=edgeItems(floorGesture);}cancelFloorGesture();if(k)applyEdgeItems(items);return;}cancelFloorGesture();if(pan)return;if(k)applyFloor(start,k);else $('floorPreviewCount').textContent='ยกเลิกการลากนอกแปลน';});
for(const event of ['pointercancel','lostpointercapture'])grid.addEventListener(event,e=>{if(floorGesture?.id===e.pointerId)cancelFloorGesture();});
window.addEventListener('blur',cancelFloorGesture);document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelFloorGesture();});
grid.addEventListener('click',e=>{if(e.detail===0){const k=e.target.closest('.cell')?.dataset.key;if(k){if(editing&&canEditFloor())studioClick(k,map.cells[k]?k:null);else if(!editing)select(k);}}});
for(const b of $('floorGroups').querySelectorAll('button'))b.onclick=()=>{cancelFloorGesture();floorGroup=b.dataset.floorGroup;if(floorCategory(tool)!=='common'&&floorCategory(tool)!==floorGroup)tool='select';refreshTools();window.office3D?.sync();};
for(const b of $('floorExpand').querySelectorAll('[data-expand]'))b.onclick=()=>{if(!canEditFloor())return;let q;try{q=floor.extend(map,b.dataset.expand,Number($('floorExpandCount').value));}catch(e){studioNotify(e.message);return;}if(!confirm(`เพิ่มพื้นที่ ${q.added} ช่อง (${q.plan.cols} × ${q.plan.rows})?${q.removed.length?' หน้าต่างที่ขอบเดิม '+q.removed.length+' บานจะถูกลบ เพราะขอบนี้กลายเป็นพื้นที่ภายใน':''} ตรวจสอบเส้นทางเดินและตำแหน่งเฟอร์นิเจอร์ในมุม 3D ก่อนบันทึก`))return;checkpoint();map=q.plan;selected=studioSelected=null;render();fit();persist('ขยายพื้น '+q.added+' ช่อง · รักษา Desk ID เดิม');};
$('floorZoomIn').onclick=()=>{if(canEditFloor()){cancelFloorGesture();setZoom(zoom+.15);}};$('floorZoomOut').onclick=()=>{if(canEditFloor()){cancelFloorGesture();setZoom(zoom-.15);}};$('floorFit').onclick=()=>{if(canEditFloor()){cancelFloorGesture();fit();const v=$('viewport');v.scrollLeft=Math.max(0,(v.scrollWidth-v.clientWidth)/2);v.scrollTop=Math.max(0,(v.scrollHeight-v.clientHeight)/2);}};
for(const id of ['floorStroke','floorSpacing','floorRoomDoor'])$(id).addEventListener('change',cancelFloorGesture);
$('edit').onclick=()=>{if(!adminMode||!window.OC41?.isAdmin())return;editing?window.OC41.cancelEdit():window.OC41.beginEdit();};$('save').onclick=()=>{cancelFloorGesture();if(edgeDraft()&&!window.OC41?.edgeReady?.()){studioNotify('ติดตั้ง SQL 34 ก่อนบันทึกออนไลน์');return;}if(!keepOwners(map))return;window.OC41?.saveEdit();};$('search').oninput=renderPeople;$('plus').onclick=()=>setZoom(zoom+.15);$('minus').onclick=()=>setZoom(zoom-.15);$('fit').onclick=fit;$('rotate').onclick=()=>{if(!canEditFloor())return;cancelFloorGesture();rotation=(rotation+90)%360;refreshTools();};$('undo').onclick=()=>{if(canEditFloor())changeHistory(undo,redo);};$('redo').onclick=()=>{if(canEditFloor())changeHistory(redo,undo);};
$('resize').onclick=()=>{if(!canEditFloor())return;const cols=Number($('cols').value),rows=Number($('rows').value);if(!Number.isInteger(cols)||cols<4||cols>80||!Number.isInteger(rows)||rows<4||rows>50){$('status').textContent='Grid size must be 4–80 columns and 4–50 rows';return;}const outside=floor.trimBlocks(map,cols,rows);if(outside.some(k=>floor.owned(map.cells[k],protectedIds))){studioNotify('ขนาดใหม่จะตัดโต๊ะที่มีเจ้าของ · ย้ายโต๊ะก่อน');return;}if(outside.length&&!confirm('Resize will remove '+outside.length+' objects. Continue?'))return;if((cols!==map.cols||rows!==map.rows)&&Object.keys(map.edges||{}).length&&!confirm('Resize changes the perimeter. Some windows may move or be removed. Continue?'))return;checkpoint();outside.forEach(k=>delete map.cells[k]);map.cols=cols;map.rows=rows;if(edgeDraft())floor.trimWallEdges(map);for(const k of Object.keys(map.edges))if(!window.OC612_STUDIO.edgeValid(map,k))delete map.edges[k];selected=null;studioSelected=null;render();fit();persist();};
$('renumber').onclick=()=>{if(!canEditFloor())return;checkpoint();desks().sort((a,b)=>{const [ax,ay]=a[0].split(',').map(Number),[bx,by]=b[0].split(',').map(Number);return ay-by||ax-bx;}).forEach(([,c],i)=>c.label='D-'+String(i+1).padStart(3,'0'));render();persist('Desk labels renumbered. Save online to publish.');};
$('clear').onclick=()=>{if(!canEditFloor())return;if(protectedIds.size||desks().some(([,c])=>c.name)){studioNotify('ไม่สามารถล้างผังที่มีโต๊ะถูกจองอยู่');return;}if(!confirm('Clear all objects? You can undo this action.'))return;checkpoint();map.cells={};map.edges={};delete map.roomTargets;delete map.personalityBoard;if(edgeDraft())map.wallEdges={};selected=null;studioSelected=null;render();persist();};
function cleanPlan(p){const out=validate(p);for(const c of Object.values(out.cells))if(c.type==='desk'){c.name='';c.status='offline';delete c.connection;delete c.personalStatus;delete c.statusMessage;delete c.profileCaption;delete c.visualOnly;delete c.visualPose;}return out;}function officeSample(){map=cleanPlan(window.OFFICE_LAYOUT);}
$('sample').onclick=()=>{if(!canEditFloor())return;const next=cleanPlan(window.OFFICE_LAYOUT);if(!keepOwners(next))return;if(Object.keys(map.cells).length&&!confirm('Replace the current plan with a sample based on your office?'))return;checkpoint();map=next;selected=null;studioSelected=null;render();fit();persist('Loaded office sample');};
$('export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(cleanPlan(map),null,2)],{type:'application/json'}));const a=el('a');a.href=url;a.download='office-floor-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const f=$('file').files[0];if(!f)return;try{if(f.size>2000000)throw Error('File too large');const next=cleanPlan(JSON.parse(await f.text()));if(!canEditFloor()||!keepOwners(next))return;if(Object.keys(map.cells).length&&!confirm('Replace current plan?'))return;checkpoint();map=next;selected=null;studioSelected=null;render();fit();persist('Imported and saved locally');}catch(e){$('status').textContent='Import failed: '+e.message;}finally{$('file').value='';}};
$('cancel').onclick=()=>$('dialog').close();$('deskForm').onsubmit=e=>{e.preventDefault();if(!canEditFloor())return;const c=map.cells[selected];if(!c)return;checkpoint();c.label=$('deskLabel').value.trim()||c.id;$('dialog').close();drawCell(selected);renderPeople();renderDetails();refreshTools();persist();window.office3D?.sync();};document.addEventListener('keydown',e=>{if(!canEditFloor()||document.querySelector('dialog[open]')||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||e.target.isContentEditable)return;if(e.key==='Escape'&&floorGesture){cancelFloorGesture();e.preventDefault();return;}if(!e.ctrlKey&&!e.metaKey&&!e.altKey){const t={v:'select',h:'pan',m:'move',w:'wall',d:'desk',f:'aisle',b:'room',e:'erase'}[e.key.toLowerCase()];if(t){chooseFloorTool(t);e.preventDefault();return;}}if(e.key.toLowerCase()==='r'&&!e.ctrlKey&&!e.metaKey)$('rotate').click();if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('redo'):$('undo')).click();}});
